const groups=[
['Arrays & Hashing',['Two Sum','Contains Duplicate','Valid Anagram','Group Anagrams','Top K Frequent Elements','Product of Array Except Self']],['Two Pointers',['Valid Palindrome','Two Sum II','3Sum','Container With Most Water']],['Sliding Window',['Best Time to Buy and Sell Stock','Longest Substring Without Repeating Characters','Longest Repeating Character Replacement','Permutation in String','Minimum Size Subarray Sum']],['Stack',['Valid Parentheses','Min Stack','Evaluate Reverse Polish Notation','Daily Temperatures','Car Fleet']],['Binary Search',['Binary Search','Search a 2D Matrix','Koko Eating Bananas','Find Minimum in Rotated Sorted Array','Search in Rotated Sorted Array']],['Linked Lists',['Reverse Linked List','Merge Two Sorted Lists','Linked List Cycle','Remove Nth Node From End','Reorder List']],['Trees',['Invert Binary Tree','Maximum Depth of Binary Tree','Diameter of Binary Tree','Balanced Binary Tree','Same Tree','Subtree of Another Tree','Lowest Common Ancestor of a BST','Validate BST','Kth Smallest in a BST']],['Heaps',['Kth Largest Element in a Stream','Last Stone Weight','K Closest Points to Origin']],['Graphs',['Number of Islands','Clone Graph','Course Schedule','Pacific Atlantic Water Flow','Word Ladder']],['Backtracking',['Subsets','Combination Sum','Permutations','Word Search']],['Dynamic Programming',['Climbing Stairs','House Robber','Coin Change','Longest Increasing Subsequence','Word Break']],['Intervals & Greedy',['Merge Intervals','Insert Interval','Non-overlapping Intervals','Jump Game']]
];
const easy=['Two Sum','Contains Duplicate','Valid Anagram','Valid Palindrome','Best Time to Buy and Sell Stock','Valid Parentheses','Binary Search','Reverse Linked List','Merge Two Sorted Lists','Linked List Cycle','Invert Binary Tree','Maximum Depth of Binary Tree','Same Tree','Balanced Binary Tree','Climbing Stairs','Last Stone Weight'];const hard=['Word Ladder','N-Queens','Trapping Rain Water'];const problems=groups.flatMap(([topic,names])=>names.map((title,i)=>({id:`${topic.slice(0,2).toUpperCase()}-${i+1}`,title,topic,difficulty:easy.includes(title)?'Easy':hard.includes(title)?'Hard':'Medium'})));
const $=s=>document.querySelector(s);let selected=null,filter='all',topic='all';let states=JSON.parse(localStorage.getItem('interview-ready-tracker')||'{}');const status=p=>states[p.id]?.status||'new';const save=()=>localStorage.setItem('interview-ready-tracker',JSON.stringify(states));const counts=()=>Object.fromEntries(['new','redo','comfortable'].map(k=>[k,problems.filter(p=>status(p)===k).length]));
function renderTopics(){const wrap=$('#topicFilters');wrap.innerHTML='';groups.forEach(([name])=>{const b=document.createElement('button');b.className=`filter topic-filter ${topic===name?'active':''}`;b.textContent=name;b.onclick=()=>{topic=topic===name?'all':name;render()};wrap.append(b)})}
function render(){const query=$('#search').value.toLowerCase(),shown=problems.filter(p=>(filter==='all'||status(p)===filter)&&(topic==='all'||p.topic===topic)&&p.title.toLowerCase().includes(query));const c=counts();$('#totalCount').textContent=problems.length;$('#newCount').textContent=c.new;$('#redoCount').textContent=c.redo;$('#comfortableCount').textContent=c.comfortable;['all','new','redo','comfortable'].forEach(k=>{const el=$(`#${k}Badge`);if(el)el.textContent=k==='all'?problems.length:c[k]});$('#showingCount').textContent=`${shown.length} shown`;const table=$('#problemTable');table.innerHTML='';shown.forEach(p=>{const row=$('#rowTemplate').content.firstElementChild.cloneNode(true);row.classList.toggle('selected',selected?.id===p.id);row.querySelector('.dot').classList.add(status(p));row.querySelector('.id').textContent=p.id;row.querySelector('.title').textContent=p.title;row.querySelector('.topic').textContent=p.topic;const d=row.querySelector('.difficulty');d.textContent=p.difficulty;d.classList.add(p.difficulty.toLowerCase());row.onclick=()=>select(p);table.append(row)});document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));renderTopics();const next=problems.find(p=>status(p)==='redo')||problems.find(p=>status(p)==='new')||problems[0];$('#nextTitle').textContent=`Try ${next.title}`;$('#nextMeta').textContent=`${next.topic} · ${next.difficulty}`;$('#focusNext').onclick=()=>select(next)}
function select(p){selected=p;const current=status(p),note=states[p.id]?.note||'';$('#detailPanel').innerHTML=`<p class="eyebrow">${p.topic.toUpperCase()}</p><h2>${p.title}</h2><p class="detail-meta">${p.id} · ${p.difficulty}</p><p>After a real attempt, choose the status that reflects what happened. This tracker is deliberately stricter than a solved count.</p><div class="status-buttons">${[['new','Not attempted'],['redo','Needs a re-solve'],['comfortable','Comfortable']].map(([key,label])=>`<button class="status-button ${current===key?'active':''}" data-status="${key}">${label}</button>`).join('')}</div><label class="note-label" for="notes">What tripped you up?</label><textarea class="notes" id="notes" placeholder="Example: I recognized the pattern but forgot the invariant.">${note}</textarea>`;document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{states[p.id]={...states[p.id],status:b.dataset.status};save();select(p);render()});$('#notes').addEventListener('input',e=>{states[p.id]={...states[p.id],note:e.target.value,status:status(p)};save()});render()}
document.addEventListener('DOMContentLoaded',()=>{$('#search').addEventListener('input',render);document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});$('#resetAll').onclick=()=>{if(confirm('Clear every local status and note?')){states={};save();selected=null;$('#detailPanel').innerHTML='<p class="eyebrow">SELECT A PROBLEM</p><h2>Use the tracker for honest signal.</h2><p>Choose a status after you try it.</p>';render()}};render()});
